/* Smart Study S². Entire core product works without a paid AI API. */
const $=id=>document.getElementById(id);
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>{if(!d)return 'No deadline';let a=d.split('-');return a.length===3?`${a[2]}/${a[1]}/${a[0]}`:e(d)};
const now=()=>{const a=new Date();return [a.getFullYear(),String(a.getMonth()+1).padStart(2,'0'),String(a.getDate()).padStart(2,'0')].join('-')};
const roleNav={student:[['Dashboard','dashboard','⌂'],['My Classes','classes','▣'],['Planner','planner','☷'],['Papers & Tests','papers','▤'],['Reports','reports','◉']],teacher:[['Dashboard','dashboard','⌂'],['My Classes','classes','▣'],['Assignments & Tests','papers','▤'],['Submissions','submissions','☷'],['Reports','reports','◉']],parent:[['My Children','children','⌂'],['Assignments','papers','▤'],['Reports','reports','◉']],admin:[['Dashboard','dashboard','⌂'],['Global Library','papers','▤'],['Users & Classes','adminusers','▣'],['Settings','settings','⚙']]};
const state={user:null,csrf:'',view:'dashboard',date:now(),classId:null,assignmentId:null,chosenStudent:null,reportStudent:null,authRole:'student',authMode:'login',google:false,questionDraft:[],currentSubmission:null,strokes:[],draw:false};
async function api(url,method='GET',payload){const opts={method,credentials:'same-origin',headers:{}};if(method!=='GET')opts.headers['X-CSRF']=state.csrf;if(payload instanceof FormData)opts.body=payload;else if(payload!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(payload)}
 const r=await fetch(url,opts);let v;try{v=await r.json()}catch{v={detail:'Server error'}};if(!r.ok)throw new Error(typeof v.detail==='string'?v.detail:'Request unsuccessful');return v}
function toast(msg){const el=$('toast');el.textContent=msg;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3600)}
function btn(text,fn,kind='secondary'){return `<button class="btn ${kind}" onclick="${fn}">${text}</button>`}
function empty(emoji,msg){return `<div class="empty"><span>${emoji}</span>${e(msg)}</div>`}
function title(name,desc='',action=''){return `<div class="page-heading"><div><div class="eyebrow">Smart Study S² · ${e(state.user?.role||'')}</div><h1>${e(name)}</h1><p class="sub">${e(desc)}</p></div>${action}</div>`}
function metric(name,value,icon='◈',hint=''){return `<div class="stat"><span class="stat-icon">${icon}</span><div class="label">${e(name)}</div><div class="value">${e(value)}</div><div class="hint">${e(hint)}</div></div>`}
function badge(t){return `<span class="badge ${t==='approved'||t==='returned'||t==='verified'?'green':t==='pending'?'amber':t==='rejected'?'red':''}">${e(t||'')}</span>`}
function progress(k,done,total){const percent=total?Math.min(100,Math.round(done/total*100)):0;return `<div class="progress-row"><div><span>${e(k)}</span><em>${done}/${total} · ${percent}%</em></div><div class="bar"><b style="width:${percent}%"></b></div></div>`}
function fval(id){return $(id)?.value||''}
async function safe(fn){try{await fn()}catch(err){toast(err.message);console.error(err)}}
function goto(view){state.view=view;state.classId=null;state.assignmentId=null;state.currentSubmission=null;state.chosenStudent=null;render()}
function shell(){const role=state.user.role;let nav=roleNav[role]||[];$('app').innerHTML=`<div class="mobile-shade" onclick="SS.closeMenu()" id="shade"></div><div class="shell"><aside class="sidebar" id="side"><div class="brand"><div class="mark">S²</div><div><div class="brand-name">Smart Study</div><div class="brand-sub">A Path to Your Board</div></div></div><div class="nav-kicker">${e(role)} workspace</div><nav class="nav">${nav.map(([n,id,icon])=>`<button class="${state.view===id?'active':''}" onclick="SS.goto('${id}')"><span class="nav-icon">${icon}</span>${e(n)}</button>`).join('')}</nav><div class="sidebar-footer"><div class="split"><div><strong>${e(state.user.name)}</strong><br>${e(state.user.email)}</div><span>●</span></div><button class="logout" onclick="SS.logout()">↪ &nbsp; Sign out</button><p style="line-height:1.5;font-size:10px">One platform · Many schools<br>Private by design</p></div></aside><main class="main"><div class="topbar"><div class="split" style="gap:12px"><button class="menu-toggle" onclick="SS.openMenu()">☰</button><div><div class="hello">Welcome back</div><strong>${e(state.user.name)} <span style="font-weight:500;color:#8b9eae;font-size:13px">/ ${e(role)}</span></strong></div></div><div class="chip">● &nbsp; ${e(state.user.school||'Smart Study Global')}</div></div><div class="page" id="page"></div></main></div>`}
function openMenu(){$('side')?.classList.add('open');$('shade')?.classList.add('show')};function closeMenu(){$('side')?.classList.remove('open');$('shade')?.classList.remove('show')}
function loginPage(){let register=state.authMode==='register';$('app').innerHTML=`<div class="login-layout"><section class="login-aside"><div class="brand" style="padding:0"><div class="mark">S²</div><div><div class="brand-name">Smart Study</div><div class="brand-sub">A Path to Your Board</div></div></div><div><div class="globe-decor">◉</div><h1>Every school.<br>Every student.<br>One smart path.</h1><p>Join your teachers, learn together, upload your work and track your progress. Anywhere in the world.</p></div><div style="color:#a4cfdb">Made for learners, teachers and families everywhere.</div></section><section class="login-main"><div class="login-card"><div class="eyebrow">Welcome to Smart Study</div><h2>${register?'Create your account':'Sign in to your workspace'}</h2><p>${register?'Choose how you will use Smart Study. You can join any school or teacher later.':'Your classes, assignments and progress in one place.'}</p><div class="role-selector">${['student','teacher','parent'].map(r=>`<button class="${state.authRole===r?'active':''}" onclick="SS.authRole('${r}')">${r[0].toUpperCase()+r.slice(1)}</button>`).join('')}</div><form onsubmit="SS.login(event)">${register?`<div class="field"><label>Your name</label><input id="loginName" required placeholder="Full name"></div><div class="field"><label>School (optional)</label><input id="loginSchool" placeholder="Any school or independent teacher"></div>`:''}<div class="field"><label>Email address</label><input type="email" id="loginEmail" required autocomplete="username" placeholder="you@gmail.com"></div><div class="field"><label>Password</label><input type="password" id="loginPassword" required minlength="${register?10:1}" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'At least 10 characters':'Enter your password'}"></div><button class="btn" style="width:100%">${register?'Create '+state.authRole+' account':'Sign in'}</button></form>${state.google?`<div style="text-align:center;color:#899bab;margin:16px">or</div><a href="/auth/google?role=${state.authRole}" class="btn ghost" style="display:flex;width:100%;justify-content:center">G &nbsp; Continue with Google</a>`:`<div class="notice">Google sign-in can be enabled when the app owner configures OAuth credentials. Email login works now with no AI API.</div>`}<div style="text-align:center;margin-top:18px;font-size:13px">${register?'Already have an account?':'New to Smart Study?'} <button class="link-btn" onclick="SS.authMode()">${register?'Sign in':'Create an account'}</button></div><p class="footer-note">Secure role permissions · Parents require student approval · Admin access is restricted</p></div></section></div>`}
async function login(ev){ev.preventDefault();await safe(async()=>{const register=state.authMode==='register';const payload={email:fval('loginEmail'),password:fval('loginPassword'),name:fval('loginName'),school:fval('loginSchool'),role:state.authRole};const res=await api(register?'/api/register':'/api/login','POST',payload);state.user=res.user;state.csrf=res.csrf;state.view=state.user.role==='parent'?'children':'dashboard';render()})}
async function logout(){await safe(async()=>{await api('/api/logout','POST');state.user=null;state.csrf='';loginPage()})}
function authRole(r){state.authRole=r;loginPage()}function authMode(){state.authMode=state.authMode==='login'?'register':'login';loginPage()}
async function render(){if(!state.user){loginPage();return}shell();$('page').innerHTML='<div class="loading">Loading your workspace…</div>';closeMenu();await safe(async()=>{switch(state.view){case'dashboard':await renderDashboard();break;case'classes':await renderClasses();break;case'planner':await renderPlanner();break;case'papers':await renderPapers();break;case'reports':await renderReports();break;case'children':await renderChildren();break;case'submissions':await renderSubmissions();break;case'adminusers':await renderAdminUsers();break;case'settings':await renderSettings();break;default:await renderDashboard()}})}
function head(html){$('page').innerHTML=html}
async function renderDashboard(){const d=await api('/api/dashboard');const role=state.user.role;if(role==='student'){
 const r=d.report;const percent=r.tasks_total?Math.round(r.tasks_done/r.tasks_total*100):0;
 const upcomingExams=(await api('/api/exams')).exams.filter(x=>x.date>=now()).slice(0,6);
 const pendingParents=(await api('/api/parent/pending')).requests;
 head(title('Your learning dashboard','A clear view of your subjects, classes and upcoming work.',btn('+ Join a class','SS.goto("classes")'))+`<div class="grid stats">${metric('Study sessions done',r.tasks_done+'/'+r.tasks_total,'✓','Your personal study plan')}${metric('Assignments submitted',r.assignments_submitted+'/'+r.assignments_total,'▤','Across all your classes')}${metric('Average test score',r.average_score===null?'—':r.average_score+'%','★','Marked assessments')}${metric('Classes joined',r.classes_count,'▣','From any school')}</div><div class="grid two"><div class="panel"><div class="panel-title"><h2>Subject progress</h2><a href="#" onclick="SS.goto('reports');return false">Full report →</a></div>${subjectRows(r.subjects)}</div><div class="panel"><h2>Upcoming assignments</h2>${d.upcoming.length?`<div class="items">${d.upcoming.map(a=>`<div class="item"><div><div class="name">${e(a.title)}</div><div class="desc">Due ${fmt(a.due_date)} · ${e(a.kind)}</div></div>${a.submission?badge(a.submission.status):btn('View',`SS.openAssignment(${a.id})`,'secondary')}</div>`).join('')}</div>`:empty('✓','No upcoming assignments from your teachers yet.')}</div></div><div class="panel"><div class="split"><div><h2 style="margin-bottom:5px">Your personal timetable</h2><div class="small">Keep your plan separate from teachers' assignments.</div></div>${btn('Open Planner','SS.goto("planner")')}</div></div>${pendingParents.length?`<div class="panel"><div class="split"><div><h2>Parent-link approval needed</h2><p class="small">${pendingParents.length} parent request(s) awaiting your approval.</p></div>${btn('Review requests','SS.studentParentRequests()')}</div></div>`:''}${upcomingExams.length?`<div class="panel"><h2>CBSE 2027 upcoming exam dates</h2><div class="items">${upcomingExams.map(x=>`<div class="item"><div><div class="name">${e(x.subject)}</div><div class="small">${e(x.type)} · ${fmt(x.date)}</div></div>${badge(x.type)}</div>`).join('')}</div></div>`:''}`)
 }else if(role==='teacher'){head(title('Teacher dashboard','Manage your classes, worksheets and student progress.',d.teacher_verified?btn('+ Create a class','SS.createClassModal()'):'')+`${!d.teacher_verified?`<div class="notice"><strong>Teacher verification pending.</strong> Your administrator must verify this teacher account before you can create a class and share join codes.</div>`:''}<div class="grid stats">${metric('Your classes',d.classes,'▣')}${metric('Enrolled students',d.students,'◉')}${metric('Assignments',d.assignments,'▤')}${metric('Pending join requests',d.pending_joins,'✧')}</div><div class="panel"><h2>Teaching across schools</h2><p class="sub">Create one class per subject or group. Share its unique join code. Students join with their own accounts, and you can approve each request before sharing coursework.</p><div style="margin-top:17px">${btn('Manage my classes','SS.goto("classes")')}</div></div>`)}
 else if(role==='admin'){head(title('Platform overview','Manage the shared paper library and account access.')+`<div class="grid stats">${metric('Registered users',d.users,'◉')}${metric('Classes created',d.classes,'▣')}${metric('Library papers',d.papers,'▤')}${metric('Awaiting verification',d.pending_papers,'✧')}</div><div class="panel"><h2>Shared paper library</h2><p class="sub">Upload only genuine, lawfully distributed papers. All students and teachers see verified materials. Empty years and sets are not represented as genuine uploaded papers.</p><div style="margin-top:17px">${btn('Manage global library','SS.goto("papers")')}</div></div>`)}
 else{head(title('Family dashboard','Progress across your approved children.')+(d.children.length?`<div class="grid stats">${metric('Linked children',d.children.length,'◉')}${metric('Total completed tasks',d.children.reduce((a,b)=>a+b.tasks_done,0),'✓')}${metric('Submitted assignments',d.children.reduce((a,b)=>a+b.assignments_submitted,0),'▤')}${metric('Classes followed',d.children.reduce((a,b)=>a+b.classes_count,0),'▣')}</div>`:empty('👨‍👩‍👧','Link a child and ask them to approve the request to start monitoring.'))+`<div class="panel">${btn('Manage children','SS.goto("children")')}</div>`)}
}
function subjectRows(subjects){const arr=Object.entries(subjects);if(!arr.length)return empty('◫','Your subject progress appears after adding or importing study tasks.');return arr.sort((a,b)=>a[0].localeCompare(b[0])).map(([n,r])=>progress(n,r.done+r.revised,r.total+r.chapters)).join('')}
async function renderClasses(){const d=await api('/api/classes');const role=state.user.role;
 if(state.classId){await renderClassDetail(state.classId);return}
 head(title('My Classes',role==='teacher'?'Each class gets a private join code, assignments and members.':'Join teachers from any school using their own class codes.',role==='teacher'&&!state.user.teacher_verified?'':btn(role==='teacher'?'+ Create class':'+ Join with code',role==='teacher'?'SS.createClassModal()':'SS.joinClassModal()'))+`<div class="grid three">${d.classes.map(c=>`<div class="panel" style="margin:0"><div class="split"><span class="pill">${e(c.subject)}</span>${c.my_status?badge(c.my_status):''}</div><h2 style="margin:16px 0 6px">${e(c.name)}</h2><div class="small">${e(c.school||'Independent class')} · ${e(c.grade)}</div><div class="small" style="margin-top:6px">Teacher: ${e(c.teacher)} · ${c.enrolled} students</div>${c.code?`<div class="notice" style="margin-top:13px">Join code: <strong style="letter-spacing:.12em">${e(c.code)}</strong></div>`:''}<div style="margin-top:15px">${c.my_status==='pending'?badge('Waiting for teacher approval'):btn('Open class →',`SS.openClass(${c.id})`)}</div></div>`).join('')}</div>${!d.classes.length?empty('▣',role==='teacher'?'Create your first subject class to get a join code.':'No classes yet. Ask your teacher for their join code.'):''}`)}
function createClassModal(){modal(`<header><h2>Create a subject class</h2><button class="close" onclick="SS.closeModal()">×</button></header><form onsubmit="SS.createClass(event)"><div class="field"><label>Subject</label><select id="clSubject">${['Maths','English','Hindi','Science','Social Science','Artificial Intelligence','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Class name</label><input id="clName" placeholder="e.g. Grade 10 Maths Batch A" required></div><div class="formgrid"><div class="field"><label>School or institution</label><input id="clSchool" placeholder="e.g. DPS or independent"></div><div class="field"><label>Grade</label><input id="clGrade" value="Class 10"></div></div><div class="form-actions"><button class="btn">Create & get join code</button></div></form>`)}
async function createClass(ev){ev.preventDefault();await safe(async()=>{let data=await api('/api/classes','POST',{subject:fval('clSubject'),name:fval('clName'),school:fval('clSchool'),grade:fval('clGrade')});closeModal();toast('Class created. Your code is '+data.code);render()})}
function joinClassModal(){modal(`<header><h2>Join a teacher's class</h2><button class="close" onclick="SS.closeModal()">×</button></header><p class="sub">Enter the unique code from your subject teacher. They will approve your request.</p><form onsubmit="SS.joinClass(event)"><div class="field" style="margin-top:15px"><label>Class code</label><input id="joinCode" required maxlength="12" placeholder="e.g. MAT7K2" style="text-transform:uppercase;letter-spacing:.15em;font-size:20px;font-weight:800"></div><div class="form-actions"><button class="btn">Request to join</button></div></form>`)}
async function joinClass(ev){ev.preventDefault();await safe(async()=>{const d=await api('/api/classes/join','POST',{code:fval('joinCode')});closeModal();toast(d.status==='pending'?'Request sent. Await teacher approval.':'You are enrolled!');render()})}
function openClass(id){state.classId=id;render()}
function goClass(id){state.view='classes';state.classId=id;render()}
async function renderClassDetail(id){const d=await api(`/api/classes/${id}`);let c=d.class;let role=state.user.role;head(title(c.name,`${c.subject} · ${c.school||'Independent'} · ${c.grade}`,btn('← All classes','SS.goto("classes")','ghost'))+`<div class="grid two"><div><div class="panel"><div class="split"><h2>Assignments and tests</h2>${role==='teacher'?btn('+ New assignment',`SS.createAssignmentModal(${id})`,'secondary'):''}</div><div class="items">${d.assignments.map(a=>`<div class="item"><div><div class="name">${e(a.title)}</div><div class="desc">${e(a.kind)} · Due ${fmt(a.due_date)} · ${a.question_count} MCQs</div></div>${btn('Open',`SS.openAssignment(${a.id})`,'secondary')}</div>`).join('')}</div>${!d.assignments.length?empty('▤','No assignments yet.'):''}</div></div><div><div class="panel"><h2>Class details</h2><div class="small">Teacher: ${e(c.teacher)}<br>Subject: ${e(c.subject)}<br>Enrolled students: ${c.enrolled}</div>${c.code?`<div class="notice">Share join code: <strong style="font-size:20px;letter-spacing:.15em">${e(c.code)}</strong></div>`:''}</div>${role==='teacher'?`<div class="panel"><div class="panel-title"><h2>Student enrollment</h2>${btn('Record attendance',`SS.attendanceModal(${id})`,'secondary')}</div>${d.members.length?d.members.map(m=>`<div class="item" style="padding:10px;border:0;box-shadow:none"><div><div class="name">${e(m.name)}</div><div class="small">${e(m.email)}</div></div><div>${m.status==='pending'?btn('Approve',`SS.approveMember(${id},${m.student_id})`,'secondary'):badge(m.status)}</div></div>`).join(''):empty('◉','No enrollment requests yet.')}</div>`:''}</div></div>`)}
async function attendanceModal(cid){await safe(async()=>{const d=await api(`/api/classes/${cid}/attendance?day=${now()}`);modal(`<header><h2>Record class attendance</h2><button class="close" onclick="SS.closeModal()">×</button></header><div class="field"><label>Date</label><input type="date" id="attDay" value="${now()}" onchange="SS.changeAttendanceDay(${cid})"></div><div id="attStudents">${attendanceRows(d)}</div><div class="form-actions"><button class="btn" onclick="SS.saveAttendance(${cid})">Save attendance</button></div>`);})}
function attendanceRows(d){return d.members.length?d.members.map(m=>`<div class="item"><div class="name">${e(m.name)}</div><select class="form-control attChoice" data-student="${m.id}" style="width:165px">${['present','absent','late','excused','not recorded'].map(v=>`<option value="${v}" ${v===m.status?'selected':''}>${e(v)}</option>`).join('')}</select></div>`).join(''):empty('◉','Approve students before recording attendance.')}
async function changeAttendanceDay(cid){await safe(async()=>{const d=await api(`/api/classes/${cid}/attendance?day=${fval('attDay')}`);$('attStudents').innerHTML=attendanceRows(d)})}
async function saveAttendance(cid){await safe(async()=>{const records=[...document.querySelectorAll('.attChoice')].map(n=>({student_id:Number(n.dataset.student),status:n.value}));await api(`/api/classes/${cid}/attendance`,'POST',{day:fval('attDay'),records});toast('Attendance saved');closeModal()})}
async function approveMember(cid,sid){await safe(async()=>{await api(`/api/classes/${cid}/members/${sid}/approve`,'POST');toast('Student approved');render()})}
function createAssignmentModal(cid){state.questionDraft=[];modal(`<header><h2>Create assignment or mock test</h2><button class="close" onclick="SS.closeModal()">×</button></header><form onsubmit="SS.createAssignment(event)"><div class="field"><label>Title</label><input id="asTitle" placeholder="e.g. Algebra worksheet 1" required></div><div class="formgrid"><div class="field"><label>Type</label><select id="asKind" onchange="SS.toggleQuizBuilder()"><option value="worksheet">Worksheet / handwritten upload</option><option value="quiz">MCQ quiz (auto marked)</option><option value="mock">MCQ mock test</option></select></div><div class="field"><label>Due date</label><input id="asDue" type="date"></div></div><div class="field"><label>Instructions</label><textarea id="asInfo" placeholder="What should students complete?"></textarea></div><div class="field"><label>Attach worksheet PDF/image (optional)</label><input id="asFile" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></div><div class="field" id="maxScoreField"><label>Maximum marks</label><input id="asMax" type="number" min="1" max="1000" value="100"></div><div id="quizBuilder" style="display:none"><h3 style="font-family:Outfit">MCQ question builder</h3><div id="draftQuestions"></div><div class="question"><div class="field"><label>Question</label><textarea id="qText" placeholder="Write a question"></textarea></div>${[0,1,2,3].map(i=>`<div class="field"><label>Option ${'ABCD'[i]}</label><input id="qOpt${i}"></div>`).join('')}<div class="field"><label>Correct answer</label><select id="qAnswer">${[0,1,2,3].map(i=>`<option value="${i}">${'ABCD'[i]}</option>`).join('')}</select></div>${btn('+ Add MCQ to test','SS.addQuestion()','secondary')}</div></div><div class="form-actions"><button class="btn">Publish to class</button></div></form>`,cid)}
function toggleQuizBuilder(){const show=fval('asKind')!=='worksheet';$('quizBuilder').style.display=show?'block':'none';$('maxScoreField').style.display=show?'none':'block'}
function addQuestion(){let q=fval('qText'),options=[0,1,2,3].map(i=>fval('qOpt'+i));if(!q.trim()||options.some(x=>!x.trim())){toast('Enter the question and all four options.');return}state.questionDraft.push({question:q,options,answer:Number(fval('qAnswer'))});$('qText').value='';options.forEach((_,i)=>$('qOpt'+i).value='');$('draftQuestions').innerHTML=state.questionDraft.map((v,i)=>`<div class="notice">${i+1}. ${e(v.question)} · Answer ${'ABCD'[v.answer]}</div>`).join('');toast('Question added')}
async function createAssignment(ev){ev.preventDefault();await safe(async()=>{const kind=fval('asKind');let data={title:fval('asTitle'),instructions:fval('asInfo'),due_date:fval('asDue'),kind,max_score:Number(fval('asMax')||100),questions:state.questionDraft};if(kind!=='worksheet'&&!data.questions.length)throw Error('Please add at least one MCQ');const cid=Number($('modal')?.dataset.classid||state.classId);const a=await api(`/api/classes/${cid}/assignments`,'POST',data);const file=$('asFile')?.files[0];if(file){const fd=new FormData();fd.append('upload',file);await api(`/api/assignments/${a.id}/attach`,'POST',fd)}closeModal();toast('Assignment published to the class');render()})}
async function openAssignment(id){state.assignmentId=id;await safe(async()=>{const a=await api(`/api/assignments/${id}`);let role=state.user.role;let body=title(a.title,`${a.kind.toUpperCase()} · Due ${fmt(a.due_date)} · ${a.max_score} marks`,btn('← Back to class',`SS.goClass(${a.class_id})`,'ghost'));
 body+=`<div class="panel"><h2>Instructions</h2><p class="sub">${e(a.instructions||'Follow the teacher instructions and complete the activity.')}</p>${a.has_file?`<div style="margin-top:15px"><a href="/api/assignments/${a.id}/file" target="_blank">Open teacher worksheet: ${e(a.filename)} ↗</a></div>`:''}</div>`;
 if(role==='student'){
   if(a.kind==='worksheet'){body+=`<div class="panel"><h2>Submit your work</h2>${a.submission?`<div class="notice">Last submission: ${badge(a.submission.status)} ${a.submission.score!==null?'· '+e(a.submission.score)+' marks':''}<br>${e(a.submission.feedback||'')}${a.submission.has_file?`<br><a href="/api/submissions/${a.submission.id}/file" target="_blank">View your uploaded paper</a>`:''}</div>`:''}<form onsubmit="SS.submitWorksheet(event,${a.id})"><div class="field"><label>Notes or doubt (optional)</label><textarea id="wsNotes" placeholder="My handwritten work is attached…"></textarea></div><div class="field"><label>Attach photo or PDF (12 MB maximum)</label><input id="wsFile" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"></div><button class="btn">Submit to teacher</button></form></div>`}
   else if(!a.submission){body+=`<div class="panel"><h2>Answer the questions</h2><form onsubmit="SS.submitQuiz(event,${a.id})">${a.questions.map((q,i)=>`<div class="question"><strong>${i+1}. ${e(q.question)}</strong>${q.options.map((o,j)=>`<label class="option"><input type="radio" name="answer${i}" value="${j}"> ${'ABCD'[j]}. ${e(o)}</label>`).join('')}</div>`).join('')}<button class="btn">Submit and check MCQs</button></form></div>`}
   else body+=`<div class="panel"><h2>Your result</h2>${badge(a.submission.status)}<div class="stat" style="margin-top:13px"><div class="label">Score</div><div class="value">${a.submission.score??'Pending'} / ${a.max_score}</div></div><div class="notice">${e(a.submission.feedback||'Teacher review pending.')}</div>${a.submission.has_file&&a.submission.strokes.length?btn('View red-pen corrections',`SS.viewMarking(${a.submission.id})`,'secondary'):''}</div>`;
   body+=`<div class="panel"><h2>Private discussion with your teacher</h2><p class="small">Only you and this class teacher can see this conversation.</p><div id="comments"></div><div class="field"><textarea id="commentText" placeholder="Ask a question about this assignment…"></textarea></div>${btn('Send privately',`SS.sendComment(${id})`)}</div>`;
 }else if(role==='teacher'){
   body+=`<div class="panel"><h2>Student submissions</h2>${a.submissions.length?a.submissions.map(s=>`<div class="item"><div><div class="name">${e(s.student_name)}</div><div class="desc">${badge(s.status)} · Score: ${s.score??'Not marked'} ${s.has_file?'· Attached file':''}</div></div>${btn('Review',`SS.reviewSubmission(${s.id})`,'secondary')}</div>`).join(''):empty('▤','No submissions yet.')}</div>`;
   body+=`<div class="panel"><h2>Private student doubts</h2><p class="small">Choose a student to read and reply. Discussions are never visible to classmates.</p><div class="field"><select id="commentStudent" onchange="SS.loadComments(${id})"><option value="">Select an enrolled student</option></select></div><div id="comments"></div><div class="field"><textarea id="commentText" placeholder="Reply privately to the selected student…"></textarea></div>${btn('Send response',`SS.sendComment(${id})`)}</div>`;
 }
 head(body);if(role==='student')loadComments(id);else{const c=await api(`/api/classes/${a.class_id}`);$('commentStudent').innerHTML='<option value="">Select an enrolled student</option>'+c.members.filter(m=>m.status==='approved').map(m=>`<option value="${m.student_id}">${e(m.name)}</option>`).join('')}
 })}
async function submitWorksheet(ev,aid){ev.preventDefault();await safe(async()=>{const fd=new FormData();fd.append('notes',fval('wsNotes'));const file=$('wsFile').files[0];if(file)fd.append('upload',file);await api(`/api/assignments/${aid}/submit`,'POST',fd);toast('Submitted to your teacher');openAssignment(aid)})}
async function submitQuiz(ev,aid){ev.preventDefault();await safe(async()=>{const d=await api(`/api/assignments/${aid}`);let answers=d.questions.map((_,i)=>{const opt=document.querySelector(`input[name="answer${i}"]:checked`);return opt?Number(opt.value):null});const res=await api(`/api/assignments/${aid}/attempt`,'POST',{answers});toast(`You scored ${res.score}/${res.total}`);openAssignment(aid)})}
async function loadComments(id){await safe(async()=>{const role=state.user.role;const sid=role==='student'?state.user.id:Number(fval('commentStudent'));if(!sid)return;const d=await api(`/api/assignments/${id}/comments?student_id=${sid}`);$('comments').innerHTML=d.comments.length?d.comments.map(c=>`<div class="notice"><strong>${e(c.author)}</strong> · <span class="small">${e(c.created?.slice(0,10))}</span><div style="margin-top:7px;white-space:pre-wrap">${e(c.body)}</div></div>`).join(''):empty('✉','No discussion yet.')})}
async function sendComment(id){await safe(async()=>{const target=state.user.role==='student'?state.user.id:Number(fval('commentStudent'));if(!target)throw Error('Select a student');await api(`/api/assignments/${id}/comments`,'POST',{student_id:target,body:fval('commentText')});$('commentText').value='';toast('Private message sent');loadComments(id)})}
function changeDate(delta){const d=new Date(state.date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+delta);state.date=d.toISOString().slice(0,10);renderPlanner()}
function chooseDate(v){if(v){state.date=v;renderPlanner()}}
async function renderPlanner(){const d=await api('/api/planner?day='+state.date);const dateObj=new Date(state.date+'T12:00:00Z');const friendly=dateObj.toLocaleDateString('en-GB',{weekday:'long',timeZone:'UTC'});const cs=await api('/api/chapters');
 head(title('Personal study planner','Your own daily schedule. Not shared with other schools or classes.',btn('Import CBSE 2027 template','SS.importCbse()','secondary'))+`<div class="panel"><div class="split" style="flex-wrap:wrap"><div><h2 style="margin:0 0 6px">Daily timetable</h2><div class="small">${e(d.template_note||'Your personalized day')}</div></div><div class="date-controls"><button title="Previous day" onclick="SS.changeDate(-1)">‹</button><div class="date-text">${fmt(state.date)}<br><span class="small">${friendly}</span></div><button title="Next day" onclick="SS.changeDate(1)">›</button><input class="date-picker-control" aria-label="Pick another date" type="date" value="${state.date}" onchange="SS.chooseDate(this.value)" title="Jump to date"></div></div><div style="margin-top:20px">${d.tasks.length?d.tasks.map(t=>`<label class="task ${t.done?'done':''}"><input type="checkbox" ${t.done?'checked':''} onchange="SS.toggleTask(${t.id})"><div style="flex:1"><span class="task-time">${e(t.time)} ${t.source==='cbse2027'?'· CBSE template':''}</span><div class="task-title">${e(t.title)}</div></div><span class="badge">${e(t.subject)}</span></label>`).join(''):empty('▤','No study sessions on this date. Add one below.')}</div><div class="divider"></div><h3>Add a study session</h3><form onsubmit="SS.addTask(event)"><div class="formgrid"><div class="field"><label>Subject</label><select id="ptSubject">${['Maths','Science','English','Hindi','Social','AI','General'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Time (optional)</label><input id="ptTime" placeholder="e.g. 4:00–5:00 PM"></div></div><div class="field" style="margin-top:15px"><label>What will you study?</label><input id="ptTitle" required placeholder="e.g. Real Numbers revision + 10 questions"></div><div class="form-actions"><button class="btn">Add to ${fmt(state.date)}</button></div></form></div><div class="panel"><h2>Chapter checklist</h2><p class="small">Studied means you've covered it once. Revised means you can solve or recall without notes.</p>${cs.chapters.length?`<div class="items">${cs.chapters.map(c=>`<div class="item"><div style="max-width:75%"><div class="name">${e(c.title)}</div><div class="small">${e(c.subject)}</div></div><div class="checkbox-row"><label><input type="checkbox" ${c.studied?'checked':''} onchange="SS.toggleChapter(${c.id},'studied')"> Studied</label><label><input type="checkbox" ${c.revised?'checked':''} onchange="SS.toggleChapter(${c.id},'revised')"> Revised</label></div></div>`).join('')}</div>`:empty('◉','Import the CBSE 2027 template to get its subject chapter checklists.')}</div>`)}
async function addTask(ev){ev.preventDefault();await safe(async()=>{await api('/api/planner','POST',{day:state.date,subject:fval('ptSubject'),timing:fval('ptTime'),title:fval('ptTitle')});toast('Study session added');renderPlanner()})}
async function toggleTask(id){await safe(async()=>{await api(`/api/planner/${id}/toggle`,'POST');renderPlanner()})}
async function toggleChapter(id,field){await safe(async()=>{await api(`/api/chapters/${id}/toggle`,'POST',{field});renderPlanner()})}
async function importCbse(){if(!confirm('Add the optional CBSE Class 10 2027 schedule to your personal timetable? This will not affect other students.'))return;await safe(async()=>{const d=await api('/api/planner/import-cbse','POST');toast(d.added?`Imported ${d.added} sessions!`:d.message);state.date='2026-11-22';renderPlanner()})}
async function renderPapers(){const role=state.user.role;const lib=await api('/api/library');const heading=role==='admin'?'Global paper library':role==='teacher'?'Assignments & shared papers':role==='parent'?'Child assignments':'Papers & Tests';let body=title(heading,role==='admin'?'Verified papers are available to every student and teacher.':'See teacher assignments and authentic papers verified by the administrator.',role==='admin'?btn('+ Upload paper','SS.uploadPaperModal()'):'');
 if(role==='parent'){
   const c=await api('/api/parent/children');body+=`<div class="panel"><h2>Children's class participation</h2>${c.children.filter(v=>v.link_status==='approved').length?`<div class="items">${c.children.filter(v=>v.link_status==='approved').map(v=>`<div class="item"><div><div class="name">${e(v.name)}</div><div class="small">Academic progress is available in Reports.</div></div>${btn('View report',`SS.openReport(${v.id})`,'secondary')}</div>`).join('')}</div>`:empty('◉','Link your children first to see their academic records.')}</div>`;head(body);return
 }
 if(role==='teacher'){const d=await api('/api/classes');body+=`<div class="panel"><h2>Your subject classes</h2>${d.classes.length?d.classes.map(c=>`<div class="item"><div><div class="name">${e(c.name)}</div><div class="small">${e(c.subject)} · ${e(c.school||'Independent')}</div></div>${btn('Create or view tests',`SS.goClass(${c.id})`,'secondary')}</div>`).join(''):empty('▣','Create a class to upload worksheets and publish MCQ quizzes.')}</div>`}
 if(role==='student'){const d=await api('/api/classes');let all=[];for(const c of d.classes.filter(x=>x.my_status==='approved')){const v=await api(`/api/classes/${c.id}`);all.push(...v.assignments.map(a=>({...a,subject:c.subject,class_name:c.name}))) }
 body+=`<div class="panel"><h2>Your tests and worksheets</h2>${all.length?`<div class="items">${all.map(a=>`<div class="item"><div><div class="name">${e(a.title)}</div><div class="desc">${e(a.subject)} · ${e(a.class_name)} · Due ${fmt(a.due_date)}</div></div>${btn('Open',`SS.openAssignment(${a.id})`,'secondary')}</div>`).join('')}</div>`:empty('▤','Join and get approved in a teacher class to receive assignments.')}</div>`}
 body+=`<div class="panel"><div class="panel-title"><h2>Shared verified previous-year papers</h2><span class="badge green">Visible to everyone</span></div><p class="small">Only actual uploaded, verified question papers appear below. 2022–2026 slots are targets, not invented papers.</p>${lib.papers.length?`<div class="paperlist">${lib.papers.map(p=>`<div class="paper"><div class="split"><span class="pill">${e(p.subject)}</span>${badge(p.verified?'verified':'unverified')}</div><div class="heading" style="margin:13px 0 5px">${e(p.title)}</div><div class="small">${e(p.board)} · ${e(p.grade)} · ${p.year} · Set ${e(p.set||'not specified')}</div><div style="margin-top:12px;display:flex;gap:10px;align-items:center">${p.has_file?`<a href="/api/library/${p.id}/file" target="_blank">Open PDF →</a>`:''}${p.source_url?`<a href="${e(p.source_url)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}${role==='admin'&&!p.verified?btn('Verify',`SS.verifyPaper(${p.id})`,'secondary'):''}</div></div>`).join('')}</div>`:empty('▥','No verified papers have been uploaded yet.')}</div><div class="panel"><h2>Official reference archives</h2><p class="small">Use official sources for the real historical paper PDFs and current sample papers. The app does not claim automatic ingestion from these links.</p><div class="split" style="justify-content:flex-start;flex-wrap:wrap;gap:15px"><a href="https://www.cbse.gov.in/cbsenew/question-paper.html" target="_blank" rel="noopener">CBSE past papers ↗</a><a href="https://cbseacademic.nic.in/SQP_CLASSX_2026-27.html" target="_blank" rel="noopener">CBSE 2026–27 sample papers ↗</a></div></div>`;
 head(body)
}
function uploadPaperModal(){modal(`<header><h2>Add global verified-source paper</h2><button class="close" onclick="SS.closeModal()">×</button></header><p class="small">Uploaded content stays private until an administrator verifies it. Only distribute materials that you have permission to share.</p><form onsubmit="SS.uploadPaper(event)"><div class="field"><label>Paper title</label><input id="paTitle" required placeholder="e.g. CBSE 2025 Mathematics Standard Set 1"></div><div class="formgrid"><div class="field"><label>Subject</label><select id="paSubject">${['Maths','Science','English','Hindi','Social','AI'].map(v=>`<option>${v}</option>`).join('')}</select></div><div class="field"><label>Year</label><input type="number" id="paYear" min="2000" max="2100" value="2025"></div><div class="field"><label>Set / code</label><input id="paSet" placeholder="e.g. 30/1/1"></div><div class="field"><label>Grade</label><input id="paGrade" value="Class 10"></div></div><div class="field"><label>Source URL (optional)</label><input id="paURL" type="url" placeholder="https://..."></div><div class="field"><label>PDF or image</label><input id="paFile" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></div><div class="form-actions"><button class="btn">Upload for verification</button></div></form>`)}
async function uploadPaper(ev){ev.preventDefault();await safe(async()=>{const fd=new FormData();['title','subject','year','set_no','grade','source_url'].forEach((k,i)=>fd.append(k,fval(['paTitle','paSubject','paYear','paSet','paGrade','paURL'][i])));const file=$('paFile').files[0];if(file)fd.append('upload',file);await api('/api/library','POST',fd);closeModal();toast('Paper uploaded. Verify it before global release.');renderPapers()})}
async function verifyPaper(id){if(!confirm('Confirm you have checked authenticity and distribution rights for this paper?'))return;await safe(async()=>{await api(`/api/library/${id}/verify`,'POST');toast('Paper verified and visible worldwide');renderPapers()})}
async function renderReports(){const role=state.user.role;if(role==='student'){const d=await api(`/api/reports/${state.user.id}`);head(reportHTML(d,'Your progress reports','Completion across your personal planner and enrolled classes.'));return}
 if(role==='parent'){const c=await api('/api/parent/children');const approved=c.children.filter(x=>x.link_status==='approved');if(!approved.length){head(title('Reports','Progress for your linked children.')+empty('◫','Link a child and wait for their approval to view reports.'));return}if(!state.reportStudent||!approved.find(x=>x.id===state.reportStudent))state.reportStudent=approved[0].id;
 const d=await api(`/api/reports/${state.reportStudent}`);head(`<div class="page-heading"><div><div class="eyebrow">Parent reports</div><h1>${e(d.student.name)}'s report</h1><p class="sub">Select a child to see separate progress.</p></div><select class="form-control" style="width:220px" onchange="SS.openReport(Number(this.value))">${approved.map(x=>`<option value="${x.id}" ${x.id===state.reportStudent?'selected':''}>${e(x.name)}</option>`).join('')}</select></div>`+reportPanels(d));return}
 if(role==='teacher'){let d=await api('/api/classes');let unique=new Map();for(const c of d.classes){const info=await api(`/api/classes/${c.id}`);for(const m of info.members.filter(x=>x.status==='approved'))unique.set(m.student_id,m)}let students=Array.from(unique.values());let body=title('Class reports','View students enrolled in your own classes and their academic activity.');body+=`<div class="panel"><h2>Enrolled students</h2>${students.length?students.map(v=>`<div class="item"><div><div class="name">${e(v.name)}</div><div class="small">${e(v.email)}</div></div>${btn('View report',`SS.openReport(${v.student_id})`,'secondary')}</div>`).join(''):empty('◫','No approved students to report yet.')}</div>`;head(body);if(state.reportStudent&&unique.has(state.reportStudent)){const report=await api(`/api/reports/${state.reportStudent}`);$('page').insertAdjacentHTML('beforeend',reportPanels(report))}return}
 head(title('Platform reports','View aggregated usage. Avoid exposing student-private discussions to administrators.')+empty('◫','Platform-wide analytics will be available after more real users join.'))}
function reportHTML(d,t,desc){return title(t,desc)+reportPanels(d)}
function reportPanels(d){return `<div class="grid stats">${metric('Personal tasks complete',d.tasks_done+'/'+d.tasks_total,'✓')}${metric('Assignments submitted',d.assignments_submitted+'/'+d.assignments_total,'▤')}${metric('Average test score',d.average_score===null?'—':d.average_score+'%','★')}${metric('Chapters revised',d.chapters_revised+'/'+d.chapters_total,'▣')}</div><div class="grid two"><div class="panel"><h2>Subject-by-subject completion</h2>${subjectRows(d.subjects)}</div><div class="panel"><h2>Overall activity</h2>${progress('Personal study sessions',d.tasks_done,d.tasks_total)}${progress('Teacher assignments',d.assignments_submitted,d.assignments_total)}${progress('Revised chapters',d.chapters_revised,d.chapters_total)}${progress('Recorded attendance',d.attendance_present,d.attendance_total)}<div class="notice">Attendance is shown only when a teacher records it. Progress is calculated from the real tasks and assignments saved in this account, not fabricated scores.</div></div></div>`}
function openReport(sid){state.reportStudent=sid;state.view='reports';render()}
async function renderChildren(){const d=await api('/api/parent/children');head(title('My children','Connect your children with a request that they must approve.',btn('+ Link child','SS.linkChildModal()'))+`<div class="grid three">${d.children.map(c=>`<div class="panel"><h2>${e(c.name)}</h2><div class="small">${e(c.email)} · ${e(c.grade)}</div><div style="margin:13px 0">${badge(c.link_status)}</div>${c.link_status==='approved'?btn('View progress report',`SS.openReport(${c.id})`):'<div class="notice">Ask this student to approve the parent-link request.</div>'}</div>`).join('')}</div>${!d.children.length?empty('◉','No children linked yet. Use their registered email to send a request.'):''}`)}
function linkChildModal(){modal(`<header><h2>Link a child</h2><button class="close" onclick="SS.closeModal()">×</button></header><p class="small">The student must sign into their own account and approve this request. Knowing an email does not grant access.</p><form onsubmit="SS.linkChild(event)"><div class="field"><label>Child's registered email address</label><input id="childEmail" required type="email" placeholder="student@example.com"></div><div class="form-actions"><button class="btn">Send approval request</button></div></form>`)}
async function linkChild(ev){ev.preventDefault();await safe(async()=>{await api('/api/parent/request','POST',{student_email:fval('childEmail')});closeModal();toast('Approval request sent to child');renderChildren()})}
async function renderSubmissions(){const c=await api('/api/classes');let submissions=[];for(const x of c.classes){const d=await api(`/api/classes/${x.id}`);for(const a of d.assignments){const details=await api(`/api/assignments/${a.id}`);for(const s of details.submissions)submissions.push({...s,assignment:a.title,subject:x.subject,max_score:a.max_score})}}head(title('Review submissions','Mark answer sheets, add red-pen corrections and reply privately.')+`<div class="panel"><h2>Submitted work</h2>${submissions.length?submissions.sort((a,b)=>b.submitted?.localeCompare(a.submitted)).map(s=>`<div class="item"><div><div class="name">${e(s.student_name)} · ${e(s.assignment)}</div><div class="desc">${e(s.subject)} · ${badge(s.status)} · ${s.score===null?'Awaiting marks':s.score+'/'+s.max_score} ${s.has_file?'· Attachment available':''}</div></div>${btn('Review',`SS.reviewSubmission(${s.id})`,'secondary')}</div>`).join(''):empty('▤','Students’ submitted worksheets and tests appear here.')}</div>`)}
async function reviewSubmission(sid){await safe(async()=>{const s=await api(`/api/submissions/${sid}`);state.currentSubmission=s;state.strokes=s.strokes||[];let html=`<header><h2>Review student submission</h2><button class="close" onclick="SS.closeModal()">×</button></header><div class="small">Submitted: ${e(s.submitted?.slice(0,10)||'')} · ${e(s.filename||'Online quiz')}</div>${s.has_file?`<div style="margin:16px 0"><a target="_blank" href="/api/submissions/${sid}/file">Open original attachment ↗</a></div>`:''}${s.has_file&&s.mime.startsWith('image/')?`<div class="notice">Draw directly on the image with a mouse, pen or touch. Red strokes are saved when you return marks.</div><div class="canvaswrap" id="drawWrap"><img src="/api/submissions/${sid}/file" id="markImage" alt="Uploaded answer sheet"><canvas id="penCanvas"></canvas></div><div class="form-actions" style="justify-content:flex-start">${btn('Clear red strokes','SS.clearStrokes()','ghost')}</div>`:s.has_file&&s.mime==='application/pdf'?'<div class="notice">PDF is available to review in a new tab. Red-pen canvas in this version supports uploaded JPG/PNG/WEBP images; enter written feedback for PDFs.</div>':''}<div class="field" style="margin-top:20px"><label>Score / marks</label><input type="number" id="markScore" step="0.5" min="0" value="${s.score??0}"></div><div class="field"><label>Teacher feedback</label><textarea id="markFeedback" placeholder="Explain errors and next steps…">${e(s.feedback)}</textarea></div><div class="form-actions"><button class="btn" onclick="SS.saveMark(${sid})">Return marked work</button></div>`;modal(html);if(s.has_file&&s.mime.startsWith('image/')){let img=$('markImage');img.onload=()=>initPen();if(img.complete)initPen()}})}
function initPen(){const img=$('markImage'),canvas=$('penCanvas');if(!img||!canvas)return;const draw=()=>{const r=img.getBoundingClientRect();canvas.width=Math.floor(r.width*devicePixelRatio);canvas.height=Math.floor(r.height*devicePixelRatio);canvas.style.height=r.height+'px';const ctx=canvas.getContext('2d');ctx.scale(devicePixelRatio,devicePixelRatio);ctx.strokeStyle='#df202e';ctx.lineWidth=2.8;ctx.lineCap='round';ctx.lineJoin='round';for(const stroke of state.strokes){if(!stroke.length)continue;ctx.beginPath();stroke.forEach((p,i)=>{if(!i)ctx.moveTo(p[0]*r.width,p[1]*r.height);else ctx.lineTo(p[0]*r.width,p[1]*r.height)});if(stroke.length===1)ctx.lineTo(stroke[0][0]*r.width+1,stroke[0][1]*r.height+1);ctx.stroke()}};draw();canvas.onpointerdown=ev=>{ev.preventDefault();canvas.setPointerCapture(ev.pointerId);state.draw=true;state.strokes.push([]);point(ev,canvas);draw()};canvas.onpointermove=ev=>{if(!state.draw)return;point(ev,canvas);draw()};canvas.onpointerup=()=>state.draw=false;canvas.onpointercancel=()=>state.draw=false}
function point(ev,canvas){const r=canvas.getBoundingClientRect();const x=Math.max(0,Math.min(1,(ev.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(ev.clientY-r.top)/r.height));state.strokes.at(-1)?.push([x,y])}
function clearStrokes(){state.strokes=[];initPen()}
async function saveMark(sid){await safe(async()=>{const val=Number(fval('markScore'));await api(`/api/submissions/${sid}/mark`,'POST',{score:val,feedback:fval('markFeedback'),strokes:state.strokes});closeModal();toast('Marks and red-pen corrections returned');if(state.view==='submissions')renderSubmissions();else if(state.assignmentId)openAssignment(state.assignmentId)})}
async function viewMarking(sid){const s=await api(`/api/submissions/${sid}`);state.strokes=s.strokes||[];modal(`<header><h2>Your returned answer sheet</h2><button class="close" onclick="SS.closeModal()">×</button></header><div class="notice">Score: <strong>${e(s.score)}</strong><br>${e(s.feedback)}</div><div class="canvaswrap" id="drawWrap"><img src="/api/submissions/${sid}/file" id="markImage"><canvas id="penCanvas" style="pointer-events:none"></canvas></div>`);const img=$('markImage');img.onload=()=>{initPen();$('penCanvas').style.pointerEvents='none'};if(img.complete){initPen();$('penCanvas').style.pointerEvents='none'}}
async function renderAdminUsers(){const d=await api('/api/admin/users');head(title('Users & classes','View registered accounts. Admin rights are never self-assigned.')+`<div class="panel"><h2>Registered users (${d.users.length} shown)</h2><div style="overflow-x:auto"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>School</th><th>Verification</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${e(u.name)}</td><td>${e(u.email)}</td><td>${badge(u.role)}</td><td>${e(u.school||'—')}</td><td>${u.role==='teacher'?(u.teacher_verified?badge('approved'):btn('Verify teacher',`SS.verifyTeacher(${u.id})`,'secondary')):'—'}</td></tr>`).join('')}</tbody></table></div></div><div class="panel" id="adminClasses"><h2>Classes across schools</h2><div class="small">Manage class visibility without exposing students’ private conversations.</div><div class="notice">Loading class list…</div></div>`);const cs=await api('/api/admin/classes');$('adminClasses').innerHTML=`<h2>Classes across schools</h2>${cs.classes.length?cs.classes.map(c=>`<div class="item"><div><div class="name">${e(c.name)} · ${e(c.subject)}</div><div class="small">${e(c.school)} · ${e(c.teacher)} · ${c.enrolled} students</div></div>${btn(c.suspended?'Restore class':'Suspend class',`SS.toggleClassSuspension(${c.id})`,c.suspended?'secondary':'ghost')}</div>`).join(''):empty('▣','No classes created yet.')}`}
async function toggleClassSuspension(id){if(!confirm('Change this class availability for its teacher and students?'))return;await safe(async()=>{const d=await api(`/api/admin/classes/${id}/toggle-suspend`,'POST');toast(d.suspended?'Class suspended':'Class restored');renderAdminUsers()})}
async function verifyTeacher(id){if(!confirm('Only verify a teacher after checking their identity and school affiliation. Continue?'))return;await safe(async()=>{await api(`/api/admin/users/${id}/verify-teacher`,'POST');toast('Teacher verified');renderAdminUsers()})}
async function renderSettings(){head(title('Platform settings','Configuration for an online installation.')+`<div class="panel"><h2>Deployment readiness</h2><div class="notice">Google OAuth requires the app owner to configure a Google OAuth Client ID, Client Secret and redirect URL. No paid AI API is required for any of the core classroom features.</div><div class="items"><div class="item"><div><div class="name">Class join codes</div><div class="small">Created per teacher class, with manual student approval.</div></div>${badge('enabled')}</div><div class="item"><div><div class="name">Private student-teacher threads</div><div class="small">Visible only to the student and own class teacher.</div></div>${badge('enabled')}</div><div class="item"><div><div class="name">Administrator access</div><div class="small">Provisioned using server environment variables, never public sign-up.</div></div>${badge('restricted')}</div><div class="item"><div><div class="name">AI answer marking</div><div class="small">Not included. Teachers mark descriptive answers manually; MCQs are auto-scored.</div></div>${badge('optional later')}</div></div></div>`)}
function modal(html,cid){if($('modalBg'))$('modalBg').remove();const div=document.createElement('div');div.className='modal-bg';div.id='modalBg';div.onclick=ev=>{if(ev.target===div)closeModal()};div.innerHTML=`<div class="modal" id="modal" ${cid?`data-classid="${cid}"`:''}>${html}</div>`;document.body.appendChild(div)}
function closeModal(){$('modalBg')?.remove()}
async function studentParentRequests(){const d=await api('/api/parent/pending');if(d.requests.length){const html=`<header><h2>Parent access requests</h2><button class="close" onclick="SS.closeModal()">×</button></header><p class="small">Only approve someone who is actually your parent or guardian. Approval grants read-only access to your progress.</p>${d.requests.map(r=>`<div class="item"><div><div class="name">${e(r.parent)}</div><div class="small">${e(r.email)}</div></div><div style="display:flex;gap:7px">${btn('Approve',`SS.parentDecision(${r.id},'approve')`)}${btn('Reject',`SS.parentDecision(${r.id},'reject')`,'ghost')}</div></div>`).join('')}`;modal(html)}}
async function parentDecision(id,action){await safe(async()=>{await api(`/api/parent/links/${id}/${action}`,'POST');toast('Parent request '+(action==='approve'?'approved':'rejected'));closeModal()})}
const SS={goto,login,logout,authRole,authMode,openMenu,closeMenu,createClassModal,createClass,joinClassModal,joinClass,openClass,goClass,approveMember,attendanceModal,changeAttendanceDay,saveAttendance,createAssignmentModal,toggleQuizBuilder,addQuestion,createAssignment,openAssignment,submitWorksheet,submitQuiz,loadComments,sendComment,changeDate,chooseDate,addTask,toggleTask,toggleChapter,importCbse,uploadPaperModal,uploadPaper,verifyPaper,openReport,linkChildModal,linkChild,reviewSubmission,saveMark,clearStrokes,viewMarking,parentDecision,studentParentRequests,verifyTeacher,toggleClassSuspension,closeModal};window.SS=SS;
(async()=>{try{const s=await api('/api/status');state.google=s.google_login_enabled;const x=await api('/api/me');state.user=x.user;state.csrf=x.csrf;state.view=state.user.role==='parent'?'children':'dashboard';await render();if(state.user.role==='student')studentParentRequests()}catch{state.user=null;loginPage()}})();
